#include "fcb_test.h"

#include "flash_map/flash_map.h"

struct fcb2 test_fcb;

struct flash_sector_range test_fcb_ranges[] = {
    [0] = {
        .fsr_flash_area = {
            .fa_device_id = 0,
            .fa_off = 0,
            .fa_size = 0x10000, /* 64K */
        },
        .fsr_range_start = 0,
        .fsr_first_sector = 0,
        .fsr_sector_size = 0x4000, /* 16 K */
        .fsr_sector_count = 4,
        .fsr_align = 1,
    },
};

void
fcb_test_wipe(void)
{
    int i;
    int rc;
    struct flash_area *fap;

    for (i = 0; i < sizeof(test_fcb_ranges) / sizeof(test_fcb_ranges[0]); i++) {
        fap = &test_fcb_ranges[i].fsr_flash_area;
        rc = flash_area_erase(fap, 0, fap->fa_size);
        TEST_ASSERT(rc == 0);
    }
}

int
fcb_test_empty_walk_cb(struct fcb2_entry *loc, void *arg)
{
    TEST_ASSERT(0);
    return 0;
}

uint8_t
fcb_test_append_data(int msg_len, int off)
{
    return (msg_len ^ off);
}

int
fcb_test_data_walk_cb(struct fcb2_entry *loc, void *arg)
{
    uint16_t len;
    uint8_t test_data[128];
    int rc;
    int i;
    int *var_cnt = (int *)arg;

    len = loc->fe_data_len;

    TEST_ASSERT(len == *var_cnt);

    rc = fcb2_read(loc, 0, test_data, len);
    TEST_ASSERT(rc == 0);

    for (i = 0; i < len; i++) {
        TEST_ASSERT(test_data[i] == fcb_test_append_data(len, i));
    }
    (*var_cnt)++;
    return 0;
}

int
fcb_test_cnt_elems_cb(struct fcb2_entry *loc, void *arg)
{
    struct append_arg *aa = (struct append_arg *)arg;
    int idx;

    idx = loc->fe_sector;
    aa->elem_cnts[idx]++;
    return 0;
}

int
fcb_tc_init_fcb(uint8_t sector_count)
{
    struct fcb2 *fcb;

    fcb = &test_fcb;
    memset(fcb, 0, sizeof(*fcb));
    fcb->f_sector_cnt = sector_count;
    fcb->f_ranges = test_fcb_ranges; /* XXX */
    fcb->f_range_cnt = 1;
    test_fcb_ranges[0].fsr_sector_count = sector_count;
    test_fcb_ranges[0].fsr_flash_area.fa_size =
        test_fcb_ranges[0].fsr_sector_size * sector_count;

    return fcb2_init(fcb);
}

void
fcb_tc_pretest(uint8_t sector_count)
{
    int rc = 0;

    fcb_test_wipe();
    rc = fcb_tc_init_fcb(sector_count);
    if (rc != 0) {
        printf("fcb_tc_pretest rc == %x, %d\n", rc, rc);
        TEST_ASSERT(rc == 0);
    }
}

