int
fcb2_elem_crc16(struct fcb2_entry *loc, uint16_t *c16p)
{
    uint8_t tmp_str[FCB2_TMP_BUF_SZ];
    int blk_sz;
    uint16_t crc16;
    uint32_t off;
    uint32_t end;
    int rc;

