static int
fcb2_read_entry(struct fcb2_entry *loc)
{
    uint8_t buf[FCB2_ENTRY_SIZE];
    uint8_t entry_crc;
    uint32_t entry_offset;
    uint32_t offset;
    uint16_t len;
    int rc;

    assert(loc != NULL);
    entry_offset = fcb2_entry_location_in_range(loc);
    /* Check that the entry metadata location is still within the sector,
     * past the sector header. When the sector is almost full, there may
     * not be enough space for another entry metadata record. */
    if (entry_offset < (loc->fe_sector - loc->fe_range->fsr_first_sector) *
        loc->fe_range->fsr_sector_size +
        fcb2_len_in_flash(loc->fe_range, sizeof(struct fcb2_disk_area))) {
        return FCB2_ERR_NOVAR;
    }
    rc = flash_area_read_is_empty(&loc->fe_range->fsr_flash_area,
        entry_offset, buf, sizeof(buf));
    if (rc < 0) {
        /* Error reading from flash */
        return FCB2_ERR_FLASH;
    } else if (rc == 1) {
        /* Entry not filled on flash */
        return FCB2_ERR_NOVAR;
